// No app navigation, settings, notifications or sample introductions here.
function entryHeader(back=false){return`<header class="entry-header">${back?`<button class="back-button" data-action="auth-view" data-view="welcome">${icon('back')}Back</button>`:`<span class="wordmark">${brand}blinddate<span class="brand-period">.</span></span>`}</header>`;}
function entryPage(){
  const loading=account.loading,screen=account.screen;
  if(screen==='sign-up'||screen==='log-in'){
    const signup=screen==='sign-up';
    return`<div class="entry-shell">${entryHeader(true)}<main class="account-page" id="entry-content"><span class="entry-symbol">${icon(signup?'heart':'spark')}</span><h1 tabindex="-1">${signup?'Your next<br><em>chapter starts here.</em>':'Welcome<br><em>back.</em>'}</h1><p class="entry-description">${signup?'Create your account. Then we’ll get to know the person behind it.':'Log in to pick up your story.'}</p><form class="account-form" novalidate aria-busy="false"><div class="field"><label for="account-email">Email</label><input class="input" id="account-email" name="email" type="email" autocomplete="email" inputmode="email" maxlength="254" value="${esc(account.email||'')}" required></div><div class="field"><label for="account-password">Password</label><div class="password-field"><input class="input" id="account-password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="${signup?8:1}" maxlength="128" required aria-describedby="password-hint"><button type="button" class="password-toggle" data-action="auth-password" aria-pressed="false" aria-label="Show password">Show</button></div><p class="caption" id="password-hint">${signup?'At least 8 characters. Make it yours.':'Your password is case-sensitive.'}</p></div><p class="field-error" data-auth-error role="alert" ${account.error?'':'hidden'}>${esc(account.error||'')}</p><button type="submit" class="button primary account-submit">${signup?'Create account':'Log in'}${icon('arrow')}</button></form><button class="entry-switch" data-action="auth-view" data-view="${signup?'log-in':'sign-up'}">${signup?'Already have an account? Log in':'New here? Create an account'}</button><p class="entry-privacy">${icon('lock')} Your email is never shown to your date.</p></main></div>`;
  }
  if(screen==='confirm')return`<div class="entry-shell">${entryHeader(true)}<main class="account-page" id="entry-content"><span class="entry-symbol">${icon('heart')}</span><h1 tabindex="-1">Check your<br><em>inbox.</em></h1><p class="entry-description">If your email needs confirmation, you’ll find a link in your inbox. Open it in this browser, then continue here.</p><div class="entry-confirm-note"><strong>${esc(account.email)}</strong><p>Already confirmed your email? Log in to start your private profile.</p></div>${button('Go to log in','auth-view','primary','data-view="log-in"','arrow')}<p class="caption entry-confirm-caption">Check spam too. Your app tabs appear after your profile is complete.</p></main></div>`;
  return`<div class="entry-shell">${entryHeader()}<main id="entry-content" class="entry-welcome"><div class="entry-photo"><img src="assets/first-hello.webp" alt="A first-date moment, with faces out of frame"><span>${icon('heart')} A little mystery. A real connection.</span></div><div class="entry-story"><h1 tabindex="-1">Meet the person.<br><em>Feel the spark.</em></h1><p class="entry-description">A blind date built around who you are — and who you’d love to meet.</p><ol class="entry-steps"><li>${icon('spark')}<span>Connect through personality.</span></li><li>${icon('calendar')}<span>Agree on a time and place.</span></li><li>${icon('heart')}<span>Meet first. Reveal only if it’s mutual.</span></li></ol></div><div class="entry-actions" ${loading?'aria-busy="true"':''}>${button(loading?'Opening blinddate…':'Create account','auth-view','primary',`data-view="sign-up" ${loading?'disabled':''}`,'arrow')}<button class="entry-switch" data-action="auth-view" data-view="log-in" ${loading?'disabled':''}>Already have an account? Log in</button>${account.error?`<p class="field-error" role="alert">${esc(account.error)}</p><button class="entry-switch" data-action="auth-retry">Try connecting again</button>`:''}<p class="caption">18+ · Your photos stay private until a mutual reveal.</p></div></main></div>`;
}
